"use client";

// Name → /api/resolve → the user confirms which Cala entity they mean
// (Cala has 5 "Inventure"s, so a match is never taken on name alone).

import { useEffect, useId, useRef, useState } from "react";

import { ApiError, resolve } from "@/lib/api";
import type { EntityKind, EntityRef } from "@/lib/types";

type State =
  | { status: "idle" }
  | { status: "loading" }
  | { status: "error"; message: string }
  | { status: "results"; query: string; items: EntityRef[] };

export interface EntityPickerProps {
  kind: EntityKind;
  label: string;
  placeholder: string;
  value: EntityRef | null;
  onChange: (entity: EntityRef | null) => void;
  examples?: string[];
}

export function EntityPicker({ kind, label, placeholder, value, onChange, examples = [] }: EntityPickerProps) {
  const id = useId();
  const [name, setName] = useState("");
  const [state, setState] = useState<State>({ status: "idle" });
  const abort = useRef<AbortController | null>(null);

  useEffect(() => () => abort.current?.abort(), []);

  async function search(query: string) {
    const q = query.trim();
    if (!q) return;
    abort.current?.abort();
    const ctrl = new AbortController();
    abort.current = ctrl;
    onChange(null);
    setState({ status: "loading" });
    try {
      const items = await resolve(q, kind, ctrl.signal);
      if (ctrl.signal.aborted) return;
      setState({ status: "results", query: q, items });
      // One match: pre-select it, still shown so the user can see what was picked.
      if (items.length === 1) onChange(items[0]);
    } catch (err) {
      if (ctrl.signal.aborted) return;
      setState({
        status: "error",
        message: err instanceof ApiError ? err.message : "Something went wrong.",
      });
    }
  }

  if (value) {
    return (
      <div>
        <p className="text-sm font-medium">{label}</p>
        <div className="mt-2 flex items-start justify-between gap-3 rounded-lg border border-foreground/20 bg-surface p-3">
          <EntityLine entity={value} />
          <button
            type="button"
            onClick={() => onChange(null)}
            className="shrink-0 text-sm text-muted underline-offset-2 hover:text-foreground hover:underline"
          >
            Change
          </button>
        </div>
      </div>
    );
  }

  return (
    <div>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          void search(name);
        }}
      >
        <label htmlFor={id} className="text-sm font-medium">
          {label}
        </label>
        <div className="mt-2 flex gap-2">
          <input
            id={id}
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder={placeholder}
            autoComplete="off"
            className="h-10 min-w-0 flex-1 rounded-lg border border-line bg-background px-3 outline-none placeholder:text-muted focus:border-foreground/40"
          />
          <button
            type="submit"
            disabled={!name.trim() || state.status === "loading"}
            className="h-10 shrink-0 rounded-lg bg-foreground px-4 text-sm font-medium text-background disabled:opacity-40"
          >
            {state.status === "loading" ? "Searching…" : "Find"}
          </button>
        </div>
      </form>

      {examples.length > 0 && state.status === "idle" && (
        <p className="mt-2 text-sm text-muted">
          Try{" "}
          {examples.map((ex, i) => (
            <span key={ex}>
              {i > 0 && ", "}
              <button
                type="button"
                className="underline underline-offset-2 hover:text-foreground"
                onClick={() => {
                  setName(ex);
                  void search(ex);
                }}
              >
                {ex}
              </button>
            </span>
          ))}
        </p>
      )}

      <div aria-live="polite">
        {state.status === "loading" && <p className="mt-3 text-sm text-muted">Searching Cala…</p>}
        {state.status === "error" && (
          <p className="mt-3 text-sm text-red-700 dark:text-red-400">
            {state.message}{" "}
            <button type="button" className="underline" onClick={() => void search(name)}>
              Try again
            </button>
          </p>
        )}
        {state.status === "results" && state.items.length === 0 && (
          <p className="mt-3 text-sm text-muted">
            No {kind === "investor" ? "investor" : "company"} named “{state.query}” in Cala. Check the
            spelling or try the full legal name.
          </p>
        )}
        {state.status === "results" && state.items.length > 1 && (
          <div className="mt-3">
            <p className="text-sm text-muted">
              {state.items.length} matches for “{state.query}”. Which one do you mean?
            </p>
            <ul className="mt-2 divide-y divide-line overflow-hidden rounded-lg border border-line">
              {state.items.map((e) => (
                <li key={e.id}>
                  <button
                    type="button"
                    onClick={() => onChange(e)}
                    className="w-full p-3 text-left hover:bg-surface focus-visible:bg-surface focus-visible:outline-none"
                  >
                    <EntityLine entity={e} />
                  </button>
                </li>
              ))}
            </ul>
          </div>
        )}
      </div>
    </div>
  );
}

function EntityLine({ entity }: { entity: EntityRef }) {
  return (
    <div className="min-w-0">
      <p className="flex flex-wrap items-center gap-2">
        <span className="font-medium">{entity.name}</span>
        <span className="rounded border border-line px-1.5 text-xs text-muted">{entity.type}</span>
      </p>
      <p className="mt-0.5 line-clamp-2 text-sm text-muted">
        {entity.description ?? "No description in Cala."}
      </p>
    </div>
  );
}

"use client";

// Home: "I'm raising / I'm investing" toggle, then pick the entities and go.

import { useRouter } from "next/navigation";
import { useState } from "react";

import { EntityPicker } from "@/components/EntityPicker";
import { checkPath, founderPath } from "@/lib/routes";
import type { EntityRef } from "@/lib/types";

type Mode = "founder" | "investor";

const MODES: { value: Mode; label: string; hint: string }[] = [
  { value: "founder", label: "I'm raising", hint: "Who should I pitch, and who should I skip?" },
  {
    value: "investor",
    label: "I'm investing",
    hint: "Does this startup conflict with my portfolio, and who backed its rivals?",
  },
];

export function HomeForm() {
  const router = useRouter();
  const [mode, setMode] = useState<Mode>("founder");
  const [company, setCompany] = useState<EntityRef | null>(null);
  const [fund, setFund] = useState<EntityRef | null>(null);
  const [startup, setStartup] = useState<EntityRef | null>(null);

  const ready = mode === "founder" ? company !== null : fund !== null && startup !== null;

  function go() {
    if (mode === "founder" && company) router.push(founderPath(company.id));
    if (mode === "investor" && fund && startup) router.push(checkPath(fund.id, startup.id));
  }

  return (
    <div className="mt-8 max-w-xl">
      <div role="radiogroup" aria-label="Mode" className="inline-flex rounded-lg border border-line p-1">
        {MODES.map((m) => (
          <button
            key={m.value}
            type="button"
            role="radio"
            aria-checked={mode === m.value}
            onClick={() => setMode(m.value)}
            className={`rounded-md px-4 py-1.5 text-sm font-medium transition-colors ${
              mode === m.value ? "bg-foreground text-background" : "text-muted hover:text-foreground"
            }`}
          >
            {m.label}
          </button>
        ))}
      </div>
      <p className="mt-3 text-sm text-muted">{MODES.find((m) => m.value === mode)?.hint}</p>

      <div className="mt-6 space-y-6">
        {mode === "founder" ? (
          <EntityPicker
            key="company"
            kind="company"
            label="Your company"
            placeholder="e.g. Kelluu"
            value={company}
            onChange={setCompany}
            examples={["Kelluu", "Sensofusion", "Stendr"]}
          />
        ) : (
          <>
            <EntityPicker
              key="fund"
              kind="investor"
              label="Your fund"
              placeholder="e.g. Tesi"
              value={fund}
              onChange={setFund}
              examples={["Tesi", "Maki.vc"]}
            />
            <EntityPicker
              key="startup"
              kind="company"
              label="The startup that pitched you"
              placeholder="e.g. NestAI"
              value={startup}
              onChange={setStartup}
              examples={["NestAI", "Stendr"]}
            />
          </>
        )}
      </div>

      <button
        type="button"
        onClick={go}
        disabled={!ready}
        className="mt-8 h-11 rounded-lg bg-foreground px-5 font-medium text-background disabled:opacity-30"
      >
        {mode === "founder" ? "Find who to pitch" : "Check this startup"}
      </button>
    </div>
  );
}

// App URLs in one place, so screens link to each other the same way.

export const founderPath = (companyId: string) => `/founder/${encodeURIComponent(companyId)}`;

export const checkPath = (investorId: string, companyId: string) =>
  `/check/${encodeURIComponent(investorId)}/${encodeURIComponent(companyId)}`;

export const briefPath = (investorId: string, companyId: string) =>
  `/brief/${encodeURIComponent(investorId)}/${encodeURIComponent(companyId)}`;

import { HomeForm } from "@/components/HomeForm";

export default function Home() {
  return (
    <section>
      <h1 className="max-w-xl text-3xl font-semibold tracking-tight">
        Who&apos;s a fit, and who has a conflict.
      </h1>
      <p className="mt-3 max-w-xl text-muted">
        Pitchlist walks Cala&apos;s graph from a company to its competitors, their rounds and the
        investors behind them, and shows a source for every claim.
      </p>
      <HomeForm />
    </section>
  );
}

